const { Client } = require('pg');
/* LES IDENTIFIANTS NE SONT PLUS DANS CE CODE.

   Ils sont lus dans un fichier du volume de n8n, hors du depot et hors de
   l'export. Changer de serveur ou faire tourner le mot de passe ne demande
   plus que de reecrire ce fichier — une fois, pas cinq.

   `fs` est autorise dans les noeuds Code de cette instance. Si le fichier
   manque, l'appel echoue bruyamment : une base inaccessible doit se voir. */
const PG_CONFIG = JSON.parse(
  require('fs').readFileSync('/home/node/.n8n/isaac-pg.json', 'utf8'));

const webhookBody = ($('Webhook').item.json.body) || {};
const answer = ($input.first().json.response) || '';

const entree = {
  timestamp: Date.now(),
  sessionId: webhookBody.sessionId || null,
  message: webhookBody.message || '',
  answer: answer,
};

/* Ajout atomique : PostgreSQL concatene le nouvel element a la valeur existante.
   La lecture-modification-ecriture precedente perdait un echange des que deux
   visiteurs parlaient a Isaac en meme temps. */
const client = new Client(PG_CONFIG);
await client.connect();
try {
  await client.query(
    "INSERT INTO app_data (key, value, updated_at) VALUES ('conversations', $1::jsonb, now()) " +
    "ON CONFLICT (key) DO UPDATE SET value = " +
    "CASE WHEN jsonb_typeof(app_data.value) = 'array' THEN app_data.value || EXCLUDED.value ELSE EXCLUDED.value END, " +
    "updated_at = now()",
    [JSON.stringify([entree])]
  );
  /* Le journal est borne : au-dela de 3000 echanges, les plus anciens sortent.
     Le decoupage se fait en base, sans rapatrier tout le tableau. */
  await client.query(
    "UPDATE app_data SET value = (SELECT jsonb_agg(e) FROM (" +
    "  SELECT e FROM jsonb_array_elements(value) WITH ORDINALITY AS t(e, n)" +
    "  ORDER BY n OFFSET GREATEST(jsonb_array_length(value) - 3000, 0)" +
    ") s) WHERE key = 'conversations' AND jsonb_array_length(value) > 3000"
  );
} catch (e) {
  /* Un echec d'ecriture du journal ne doit pas priver le visiteur de sa reponse. */
  console.log('Journal des conversations indisponible :', e.message);
} finally {
  await client.end();
}

return $input.all();

/* Qui a droit au chemin rapide — celui qui n'ouvre PAS la base de connaissances.

   Une LISTE BLANCHE, pas une heuristique. « Et qui a fonde ST Digital. » fait
   six mots et n'a pas de point d'interrogation : une regle genereuse la prenait
   pour une politesse et la privait de la base. */

const body = ($input.first().json.body) || {};
const brut = String(body.message || '').trim();
const normalise = brut.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

const POLITESSES = [
  /^(bonjour|bonsoir|salut|coucou|hello|hi|hey|yo)\b/,
  /^(merci|thanks|thank you|nickel|parfait|super|genial|d'accord|daccord|ok|okay)\b/,
  /^(au revoir|a bientot|a plus|bye|bonne journee|bonne soiree|bonne fin)\b/,
  /^(ca va|ca marche|comment ca va|comment vas tu|comment vas-tu|comment allez vous|comment allez-vous|tu vas bien|how are you)\b/,
  /^(qui es tu|qui es-tu|qui etes vous|qui etes-vous|tu es qui|who are you|tu fais quoi)\b/,
  /^(oui|non|yes|no|peut etre|peut-etre|bien sur)\s*[.!]?$/,
  /^(excusez moi|excuse moi|pardon|s'il vous plait|svp)\b/,
];

/* Un mot interrogatif ou un terme metier interdisent le chemin rapide, quelle
   que soit la longueur. Ces questions ont besoin de la fiche. */
const INTERROGATIFS = /\b(qui|que|quoi|quel|quelle|quels|quelles|ou|quand|comment|combien|pourquoi|est ce|est-ce|puis je|puis-je|peux|pouvez|avez|faites|proposez|existe)\b/;
const METIER = /horaire|service|tarif|prix|adresse|localisation|situe|data ?cent|centre de donnees|rendez.?vous|rdv|cloud|securite|cybersec|certification|contact|email|courriel|telephone|ouvert|ferme|visite|gabon|cameroun|ivoire|entreprise|client|offre|solution|formation|datacenter|nkok|libreville|fonde|fondateur|siege|pays|salarie|effectif|hours|price|address|visit|appointment|office/;

const politesse = POLITESSES.some((m) => m.test(normalise));
const interrogatif = INTERROGATIFS.test(normalise);
const metier = METIER.test(normalise);

/* Le visiteur repond a une question qu'Isaac vient de poser — son nom, sa
   societe. Cela ne vaut que si sa reponse n'est pas elle-meme une question :
   sinon la conversation entiere basculait sur le chemin rapide, puisque Isaac
   termine presque toujours par une question. */
const history = body.history || [];
const dernier = history[history.length - 1];
const repondAIsaac = !!dernier && dernier.sender !== 'visitor'
  && /\?\s*$/.test(String(dernier.text || '').trim())
  && !/\?/.test(brut) && !interrogatif && !metier
  && brut.split(/\s+/).filter(Boolean).length <= 8;

const isSimple = politesse || repondAIsaac;

return [{ json: { body, isSimple, answeringOwnQuestion: repondAIsaac } }];

const body = $json.body;
const lang = body.lang === 'en' ? 'en' : 'fr';
const answeringOwnQuestion = $json.answeringOwnQuestion;
const history = body.history || [];
const lastIsaacTurn = history[history.length - 1];

let system;
let prompt;
if (answeringOwnQuestion && lastIsaacTurn) {
  system = lang === 'en'
    ? "You are Isaac, ST DIGITAL's reception assistant. You just asked the visitor a question; they are now answering it. Acknowledge their answer naturally and warmly in one or two sentences -- do not ask the same question again, and do not invent facts about ST DIGITAL."
    : "Tu es Isaac, l'assistant d'accueil de ST DIGITAL. Tu viens de poser une question au visiteur ; il y repond maintenant. Accuse reception de sa reponse naturellement et chaleureusement en une ou deux phrases -- ne repose pas la meme question, et n'invente aucun fait sur ST DIGITAL.";
  prompt = (lang === 'en' ? 'Your previous question: ' : 'Ta question precedente : ') + lastIsaacTurn.text + '\n' + (lang === 'en' ? "Visitor's answer: " : 'Reponse du visiteur : ') + (body.message || '');
} else {
  system = lang === 'en'
    ? "You are Isaac, ST DIGITAL's reception assistant. The visitor's message is short and casual (a greeting, thanks, or small talk) -- reply briefly, warmly and naturally in one or two sentences. If it is not truly casual and needs facts about ST DIGITAL, say you need more detail and invite the visitor to ask their question."
    : "Tu es Isaac, l'assistant d'accueil de ST DIGITAL. Le message du visiteur est court et informel (salutation, remerciement, ou petite conversation) -- reponds brievement, chaleureusement et naturellement en une ou deux phrases. Si ce n'est pas vraiment informel et necessite des faits sur ST DIGITAL, dis que tu as besoin de plus de details et invite le visiteur a poser sa question.";
  prompt = body.message || '';
}

/* PAS de « fetch » ici : il n'existe pas dans le bac a sable d'un noeud Code,
   et l'appel levait « ReferenceError » a chaque salutation. Le defaut est
   reste invisible tant que l'aiguillage ne menait jamais ici. */
let texte = '';
try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:11434/api/generate',
    headers: { 'Content-Type': 'application/json' },
    body: {
      model: 'qwen2.5:7b-instruct-q4_K_M',
      system,
      prompt,
      stream: false,
      keep_alive: '-1s',
      /* 8192 ET PAS 4096 : LA MEME QUE LA FICHE, ET C'EST TOUT L'INTERET.
         Ollama recharge son moteur quand la taille de contexte change, et le
         cache de prefixe part avec. Une salutation servie ici en 4096 faisait
         payer a la question SUIVANTE la re-evaluation complete de la fiche :
         253,9 secondes mesurees le 01/10, contre 0,4 seconde quand les deux
         invites partagent la meme taille. */
      options: { num_thread: 4, num_ctx: 8192, num_predict: 60, temperature: 0.4 },
    },
    json: true,
    timeout: 120000,
  });
  texte = ((data && data.response) || '').trim();
} catch (e) {
  console.log('Chemin rapide indisponible :', e.message);
}

/* PAS de repli qui se fait passer pour une reponse. La version precedente
   renvoyait la phrase d'accueil quand le modele ne repondait pas : Isaac
   disait bonjour a une vraie question, et l'on croyait qu'il avait ignore la
   personne. Une salutation a la place d'une reponse est pire qu'une erreur,
   parce qu'elle se fait passer pour un succes.

   Un chemin rapide qui echoue reprend la route normale : la question repart
   vers la fiche de reference. */
return [{ json: { body, response: texte, rapideOk: texte.length > 0 } }];

/* Faits validés par ST DIGITAL, servis sans passer par le modèle.
   ================================================================

   POURQUOI. Sur cette machine, la lecture du contexte coûte 88 % du temps de
   réponse : une question documentaire demande de cent à cent soixante-quinze
   secondes. Or les questions les plus posées à un accueil portent sur quatre
   faits qui ont une valeur unique, vérifiée, et qui doivent être restitués
   MOT POUR MOT : les horaires, l'adresse du bureau, celle du Datacenter, et
   les coordonnées.

   Ces faits portent tous la mention « [Validé par ST Digital le 24/08/2026] »
   dans la base de connaissances. Les servir depuis une table plutôt que par
   récupération documentaire les rend instantanés ET exacts : une valeur lue
   dans une table ne peut pas dériver, alors qu'une réponse générée le peut —
   et l'a déjà fait, quand Isaac a annoncé « 8h-18h, samedi 8h-12h » un jour
   où le magasin vectoriel était vide.

   C'est la seule optimisation de ce projet qui n'échange rien contre la
   vitesse. Toutes les autres coûtent quelque chose : le modèle plus petit
   coûte de la qualité, les morceaux plus courts coûtent du rappel. Celle-ci
   améliore les deux.

   CE QU'ELLE NE FAIT PAS. Elle ne reformule rien. Faire reparaphraser un fait
   validé par le modèle réintroduirait exactement le risque qu'on élimine, y
   ajouterait cent secondes, et n'apporterait rien : une phrase écrite une fois
   et relue est meilleure qu'une phrase régénérée à chaque visiteur.

   POURQUOI DES MOTIFS ET NON UNE COMPARAISON SÉMANTIQUE. Une correspondance
   par similarité demande un seuil, et un seuil mal placé produit une réponse
   FAUSSE avec aplomb — le pire résultat possible ici. Des motifs explicites se
   lisent, se testent, et se corrigent. Ils ratent des formulations : c'est
   voulu. Un raté coûte cent secondes ; une fausse correspondance coûte la
   confiance.

   RÈGLE DE PRUDENCE. Au moindre doute, on ne répond pas depuis la table et on
   laisse la recherche documentaire faire son travail. */

function normalise(texte) {
  return String(texte || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    /* Les elisions sont RECOLLEES avant le reste. Sans cela l'apostrophe
       devient une espace, « j'aimerais » s'ecrit « j aimerais », et un motif
       ecrit naturellement avec « je » ne trouve rien — en silence. Ce piege
       s'est referme quatre fois en une seule journee : on le traite ici, une
       fois, plutot qu'un motif a la fois. */
    .replace(/\b([jnmtsldc])['\u2019]/g, "$1e ")
    .replace(/\bqu['\u2019]/g, "que ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

/* Sujets qui ne doivent JAMAIS être servis depuis la table, même si la
   question mentionne par ailleurs un fait connu. « Quels sont vos horaires et
   combien coûte l'hébergement ? » ne doit pas recevoir les seuls horaires :
   la moitié de la question resterait sans réponse. */
const JAMAIS_RACCOURCI = [
  /* Contrats et engagements : aucune formule validee ne les couvre. La reponse
     sur les tarifs parle d'une proposition commerciale, ce qui ne convient pas
     a une question sur une resiliation ou une penalite. */
  /contrat|engagement|resiliation|sla|penalit|clause/,
  /* Une plainte demande un responsable, pas une phrase toute faite. */
  /\bplainte|porter plainte|reclamation/,
  /* Une tentative de detournement ne doit jamais recevoir de reponse
     preparee : elle doit passer par le modele, qui refusera. */
  /ignore (tes|les) instruction|desactive|code d acces|mot de passe|donne moi le code/,
];

/* Manieres de demander ou se trouve quelque chose. La derniere ligne compte :
   « le datacenter il est ou ? » place l'interrogatif a la fin, ce qu'aucun
   motif construit sur « ou se trouve » n'attrape. Une fois les accents retires,
   « ou » interrogatif et « ou » conjonction se confondent : on n'accepte donc
   le mot seul qu'en fin de phrase ou apres un verbe d'etat. */
const LOCALISATION = /ou se trouve|ou est|ou sont|adresse|situe|situee|localis|comment venir|comment vous rendre|(?:est|sont|situe|trouve)\s+ou\b|\bou\s*$|where is|where are|where can i find|address|located|\blocation of\b|\byour location\b|how do i get|how to get/;

/* Un acquiescement tient en quelques mots. « ok jai besoin d'un devis pour
   heberger mon site web » en fait onze : c'est une demande, et le « ok »
   n'est qu'une respiration. Sans cette limite, l'entree « acquiescement »
   correspondait en meme temps que « tarifs », la table s'abstenait faute de
   pouvoir trancher, et la question partait au modele — qui a repondu par le
   formulaire que la fiche interdit.

   Neuf mots, pas six : « merci beaucoup pour toutes ces informations, bonne
   journee » est un vrai remerciement et doit le rester. La limite n'est pas
   le garde-fou principal — les termes ci-dessous le sont — elle rattrape ce
   qu'ils laissent passer. */
const TROP_LONGUE_POUR_UNE_POLITESSE = /^\S+(\s+\S+){8,}/;

/* Les termes qui font d'une phrase une vraie demande, meme precedee d'un
   « ok » ou d'un « merci ». Ils manquaient a la liste d'exclusion. */
/* CE QUI FAIT D'UNE PHRASE UNE DEMANDE, meme precedee d'un « bonjour »,
   d'un « ok » ou d'un « merci ». Un rendez-vous demande apres un bonjour
   reste un rendez-vous demande — c'est la phrase du 01/10 qui a coute
   quarante secondes et rendu le formulaire que la fiche interdit. */
const MARQUE_DE_DEMANDE =
  /devis|cout|couts|montant|facturation|budget|heberg|coloc|abonnement|souscri|offre|solution|besoin|projet|rendez ?vous|rdv|voudrais|aimerais|souhaite|je cherche|pouvez|puis je|savoir si|visiter|rencontrer|parler a|price|cost|quote|how much|appointment|i would like|i want|i need|can you|could you/;

const FAITS = [
  {
    /* Les politesses passaient par le modele, qui regenerait a chaque fois une
       phrase deja ecrite dans la fiche — cinq secondes pour dire bonjour. Ces
       formules sont fixes : on les rend directement.

       Chaque courtoisie a la sienne. Repondre « bonjour » a un remerciement
       donne l'impression de ne pas avoir ecoute. */
    cle: "salutation",
    exige: [/^(bonjour|bonsoir|salut|coucou|hello|hi|hey|yo|bjr)\b/],
    exclut: [/\?|horaire|adresse|datacenter|tarif|prix|visite|contact|qui|que|quoi|quel|comment|combien|ou\b/,
             TROP_LONGUE_POUR_UNE_POLITESSE, MARQUE_DE_DEMANDE],
    reponse: {
      fr: "Bonjour et bienvenue chez ST DIGITAL. Comment puis-je vous aider ?",
      en: "Hello and welcome to ST DIGITAL. How may I help you?",
    },
  },
  {
    cle: "remerciement",
    /* Un acquiescement peut preceder le remerciement : « parfait, merci ».
       Sans cette tolerance, la phrase n'etait reconnue par aucun des deux. */
    exige: [/^(ok|okay|de accord|daccord|parfait|super|tres bien|genial|nickel)?[ ,]*(merci|thanks|thank you|je vous remercie)\b/],
    exclut: [/\?|horaire|adresse|datacenter|tarif|visite|contact/,
             TROP_LONGUE_POUR_UNE_POLITESSE, MARQUE_DE_DEMANDE],
    reponse: {
      fr: "Je vous en prie. N'hésitez pas si vous avez une autre question.",
      en: "You are welcome. Do let me know if you have another question.",
    },
  },
  {
    /* Acquiescer n'est pas demander. « ok », « parfait », « d'accord » ne
       reclament pas de reponse : ils demandent qu'on prenne acte. Sans cette
       entree, ces phrases partaient au modele, qui les prenait pour une
       demande et repartait dans un accueil complet. */
    cle: "acquiescement",
    exige: [/^(ok|okay|de accord|daccord|tres bien|parfait|super|genial|impeccable|nickel|ce est note|entendu|compris|ca marche|tres bien merci)\b/],
    /* Un acquiescement suivi d'une vraie question n'en est plus un. */
    exclut: [/\?|horaire|adresse|datacenter|tarif|prix|visite|contact|rendez ?vous|rdv|qui |quel|comment|combien|merci\b/,
             TROP_LONGUE_POUR_UNE_POLITESSE, MARQUE_DE_DEMANDE],
    reponse: {
      fr: "Parfait. Je reste à votre disposition si vous avez une autre question.",
      en: "Perfect. I remain at your disposal if you have another question.",
    },
  },
  {
    cle: "au_revoir",
    exige: [/^(au revoir|a bientot|a plus|bye|bonne journee|bonne soiree|bonne fin|salut a vous|a demain)\b/],
    exclut: [/\?/, TROP_LONGUE_POUR_UNE_POLITESSE, MARQUE_DE_DEMANDE],
    reponse: {
      fr: "Bonne journée, et à bientôt chez ST DIGITAL.",
      en: "Have a good day, and see you soon at ST DIGITAL.",
    },
  },
  {
    /* « Comment allez-vous ? » n'appelle pas la fiche : c'est une politesse,
       et y repondre par une presentation d'entreprise serait a cote. */
    cle: "prise_de_contact",
    exige: [/^(ca va|comment ca va|comment allez[- ]vous|comment vas[- ]tu|tu vas bien|vous allez bien|how are you)\b/],
    exclut: [TROP_LONGUE_POUR_UNE_POLITESSE, MARQUE_DE_DEMANDE],
    reponse: {
      fr: "Très bien, merci. Que puis-je faire pour vous ?",
      en: "Very well, thank you. What can I do for you?",
    },
  },
  {
    cle: "horaires",
    /* Au moins un terme d'horaire... */
    /* Frontieres de mots obligatoires : sans elles, « ouvert » se trouve dans
       « decouverte » et une question sur les journees portes ouvertes recevait
       les horaires du bureau. */
    exige: [/\bhoraires?\b|\bouverts?\b|\bouvre[zr]?\b|\bouverture\b|\bfermet|\bfermeture\b|\bferme[zr]?\b|quelle heure|heures d|opening hours|business hours|what time|when.*open|are you open|closing time/],
    /* ...et aucun de ceux-ci, qui désignent une autre question. Les horaires
       validés sont ceux du BUREAU de Libreville : une question sur la visite
       du Datacenter ou sur les portes ouvertes n'a pas la même réponse. */
    exclut: [/datacenter|data center|nkok|centre de donnees|portes ouvertes|visite|rendez vous|rdv|open day|open days|visit|appointment/],
    reponse: {
      fr: "Le bureau de Libreville est ouvert du lundi au vendredi, de 8h00 à 17h00. Il est fermé le samedi et le dimanche.",
      en: "The Libreville office is open Monday to Friday, from 8:00 am to 5:00 pm. It is closed on Saturdays and Sundays.",
    },
  },
  {
    cle: "adresse_bureau",
    /* Deux conditions : une intention de localisation ET le mot « bureau ».
       Sans la seconde, « où se trouve votre Datacenter » tomberait ici. */
    exige: [LOCALISATION,
            /bureau|siege|agence|locaux|libreville|office|branch|headquarters/],
    exclut: [/datacenter|data center|nkok|centre de donnees|data centre/],
    reponse: {
      fr: "Notre bureau de Libreville est situé à l'Immeuble Cofina, avenue Jean-Paul II, Boulevard Triomphal, à Libreville au Gabon.",
      en: "Our Libreville office is located at Immeuble Cofina, avenue Jean-Paul II, Boulevard Triomphal, in Libreville, Gabon.",
    },
  },
  {
    /* Section 12.4 de la base. Formule validee, reprise mot pour mot : la
       souverainete numerique est un sujet ou une reformulation libre derape
       vite, et c'est une question que les visiteurs posent. */
    cle: "cloud_souverain",
    exige: [/cloud souverain|souverainete|souverain|data sovereignty|sovereign cloud/],
    exclut: [/tarif|prix|cout|devis|combien/],
    reponse: {
      fr: "Oui. ST DIGITAL développe des solutions de Cloud et d'hébergement permettant notamment de répondre aux enjeux de souveraineté et de localisation des données en Afrique. Le Datacenter de Nkok au Gabon participe à cette stratégie.",
      en: "Yes. ST DIGITAL develops Cloud and hosting solutions that address data sovereignty and data localisation in Africa. The Nkok Datacenter in Gabon is part of that strategy.",
    },
  },
  {
    /* Section 12.5. */
    cle: "heberger_au_gabon",
    exige: [/heberger|hebergement|host|hosting|stocker|garder/, /(mes|nos|my|our) donnees|(mes|nos|my|our) data|au gabon|in gabon|donnees au gabon/],
    exclut: [/tarif|prix|cout|devis|combien|coloc/],
    reponse: {
      fr: "ST DIGITAL dispose d'un Datacenter à Nkok, au Gabon, destiné notamment à l'hébergement et à la sécurisation des données. Pour confirmer si votre besoin spécifique peut être couvert et dans quelles conditions, je peux vous orienter vers un expert.",
      en: "ST DIGITAL operates a Datacenter in Nkok, Gabon, intended in particular for hosting and securing data. To confirm whether your specific need can be covered and on what terms, I can put you in touch with an expert.",
    },
  },
  {
    /* Section 12.6. Le motif exige une marque de catalogue : sans elle, un
       incident de securite signale par un visiteur recevrait une plaquette
       commerciale a la place d'une alerte. */
    cle: "offre_cybersecurite",
    exige: [/faites? ?vous|est ce que vous (faites|proposez|avez)|proposez ?vous|avez ?vous|vous (faites|proposez)|do you (do|offer|provide|have)|are you|can you/, /cybersecurite|cyber securite|securite informatique|cybersecurity|security services/],
    exclut: [/tarif|prix|cout|devis|combien|intrusion|forcer|alarme|incident/],
    reponse: {
      fr: "Oui. ST DIGITAL propose des services de cybersécurité et de supervision destinés à protéger les infrastructures et les données des organisations.",
      en: "Yes. ST DIGITAL provides cybersecurity and monitoring services designed to protect organisations' infrastructure and data.",
    },
  },
  {
    /* Section 12.7. */
    cle: "offre_intelligence_artificielle",
    exige: [/faites? ?vous|est ce que vous (faites|proposez|avez)|proposez ?vous|avez ?vous|vous (faites|proposez)|do you (do|offer|provide|have)|are you|can you/, /intelligence artificielle|artificial intelligence|machine learning|\bia\b|\bai\b(?=\s*[?.!]?\s*$)/],
    exclut: [/tarif|prix|cout|devis|combien/],
    reponse: {
      fr: "Oui. ST DIGITAL accompagne les entreprises dans leurs projets d'intelligence artificielle, notamment pour l'automatisation, l'optimisation des processus et la mise en place de solutions adaptées à leurs besoins.",
      en: "Yes. ST DIGITAL supports companies in their artificial intelligence projects, in particular for automation, process optimisation and putting in place solutions suited to their needs.",
    },
  },
  {
    /* QUI EST ISAAC. Question frequente, reponse invariable : elle n'a rien
       a faire dans une generation de douze secondes.

       COURTE ET NON TECHNIQUE, volontairement. La regle du 30/09 interdit
       de decrire le fonctionnement : ni le modele, ni la machine, ni la
       chaine. Isaac dit ce qu'il FAIT, pas ce qu'il EST. */
    cle: "identite_isaac",
