   On rend un NOM et une FONCTION. Jamais une adresse electronique ni un
   telephone direct : ce sont des donnees personnelles, et la base interdit
   explicitement de communiquer les coordonnees d'un collaborateur. */
const SERVICES = {
  commercial: /commercial|vente|devis|offre/,
  technique: /technique|support|informatique|reseau|infra/,
  securite: /securite|surete|gardien/,
  rh: /ressources humaines|\brh\b|recrutement|candidature|stage/,
  site_manager: /site manager|responsable du site|directeur du site|chef de site/,
  marketing: /marketing|communication|publicite|reseaux sociaux|evenementiel/,
  admin_financier: /administratif|financier|finance|comptab|facturation|paiement|tresorerie/,
};

/* L'ANGLAIS Y A DROIT AUSSI — et cela fait gagner du temps, pas en perdre :
   « do you know him ? » partait au modele faute d'un motif anglais, et
   revenait avec un formulaire de visite au lieu du nom de la personne. La
   table repond maintenant, instantanement. */
const DEMANDE_ANNUAIRE =
  /qui (est|s ?'?occupe|gere|dirige|travaille|contacter)|responsable|chef de|en charge de|a qui (je )?(dois |peux )?(m ?'?adresser|parler)|organigramme|votre equipe|le personnel|service (marketing|commercial|technique|financier)|who (is|are|works|handles|manages|should i)|in charge of|do you know (him|her|them|a |someone|anyone)|does .{0,20}work (here|with you)|can i (speak|talk) to|may i (speak|talk) to|your team|the staff|org ?chart/;

/* QUI EST NOMME DANS LA QUESTION. « I want to see Rodrigue, do you know
   him ? » porte sur une personne precise : repondre par la liste de toute
   l'equipe serait a peine mieux qu'un formulaire de visite. Rodrigue est a
   l'annuaire, service commercial — l'information existait, personne
   n'allait la chercher.

   On CONFIRME d'abord, on demande ensuite. C'est l'inverse de ce que
   faisait la borne, qui reclamait un nom et un motif avant d'avoir dit si
   la personne etait seulement la.

   Trois lettres au minimum : un prenom plus court se retrouverait au milieu
   de n'importe quel mot. */
function personneNommee(net, equipe) {
  for (const membre of equipe) {
    const nom = String((membre && membre.name) || '').trim();
    if (nom.length < 3) continue;
    const cle = nom.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (net.indexOf(cle) >= 0) return { nom: nom, service: membre.service || null };
  }
  return null;
}

