function phrasePersonne(en, qui) {
  if (!qui) {
    return en
      ? 'I have nobody by that name registered for this site. I can pass your request on to the team, who will point you in the right direction.'
      : "Je n'ai personne de ce nom enregistré pour ce site. Je peux transmettre votre demande à l'équipe, qui vous orientera.";
  }
  const brut = String(qui.service || '');
  if (en) {
    const srv = SERVICES_EN[brut] || null;
    return 'Yes, ' + qui.nom + (srv ? ' is part of our ' + srv + ' team' : ' is part of our team')
      + '. If you have come to see them, tell me your name and I will let them know.';
  }
  const srv = SERVICES_FR[brut] || null;
  return 'Oui, ' + qui.nom + (srv ? ' fait partie de notre équipe ' + srv : ' fait partie de notre équipe')
    + '. Si vous venez rencontrer cette personne, donnez-moi votre nom et je la préviens.';
}

/* Ce que l'annuaire repond quand la question porte sur un SERVICE. */
function phraseAnnuaire(en, cle, a, b) {
  if (cle === 'videService') {
    return en
      ? 'I have nobody registered for the ' + a + ' team on this site. I can pass your request on to the team, who will point you in the right direction.'
      : "Je n'ai personne d'enregistré pour le " + a + " sur ce site. Je peux transmettre votre demande à l'équipe, qui vous orientera.";
  }
  if (cle === 'service') {
    return en
      ? 'For ' + a + ', you can speak to ' + b + '. Would you like me to pass your request on?'
      : 'Pour le service ' + a + ', vous pouvez vous adresser à ' + b + '. Souhaitez-vous que je transmette votre demande ?';
  }
  return en
    ? 'Our team on site includes ' + b + '. Tell me what you are looking for and I will point you to the right person.'
    : 'Notre équipe sur place comprend ' + b + '. Dites-moi ce que vous cherchez et je vous oriente vers la bonne personne.';
}

async function chercheAnnuaire(q) {
  const net = q.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  if (!DEMANDE_ANNUAIRE.test(net)) return null;

  const client = new Client(PG_CONFIG);
  await client.connect();
  let equipe = [];
  try {
    const r = await client.query("SELECT value FROM app_data WHERE key = 'staff'");
    equipe = (r.rows.length && r.rows[0].value) || [];
  } finally {
    await client.end();
  }
  if (!equipe.length) return null;

  /* Une personne nommee l'emporte : c'est la question la plus precise
     qu'on puisse poser a un annuaire. */
  const qui = personneNommee(net, equipe);
  if (qui) return phrasePersonne(langue === 'en', qui);

  /* Un service demande explicitement ? On ne rend que celui-la. */
  let vises = equipe;
  let service = null;
  for (const cle of Object.keys(SERVICES)) {
    if (SERVICES[cle].test(net)) { service = cle; break; }
  }
  if (service) vises = equipe.filter((m) => m.service === service);

  /* Le service est reconnu mais personne n'y est enregistre. Le dire tout de
     suite vaut mieux que de laisser la question partir dans la recherche
     documentaire pour en revenir a cote du sujet. */
  if (service && !vises.length) {
    const nom = langue === 'en'
      ? (SERVICES_EN[service] || service.replace('_', ' '))
      : service.replace('_', ' ').replace('admin financier', 'service administratif et financier');
    return phraseAnnuaire(langue === 'en', 'videService', nom);
  }
  if (!vises.length) return null;

  const noms = vises.slice(0, 6).map((m) => m.name).filter(Boolean);
  if (!noms.length) return null;

  const liste = noms.length === 1 ? noms[0]
    : noms.slice(0, -1).join(', ') + ' et ' + noms[noms.length - 1];

  return phraseAnnuaire(langue === 'en', service ? 'service' : 'equipe',
    service ? (langue === 'en' ? (SERVICES_EN[service] || service.replace('_', ' '))
                               : service.replace('_', ' ')) : null, liste);
}


/* 1. Les motifs d'abord : exacts, instantanes, sans seuil a regler. */
let trouve = reponseValidee(question, langue, body.mode);
let voie = trouve ? 'motif' : null;

/* L'annuaire vient juste apres les motifs : il repond a « qui s'occupe de... »
   avec ce que le back-office contient a l'instant. */
if (!trouve) {
  try {
    const nomme = await chercheAnnuaire(question);
    if (nomme) { trouve = { cle: 'annuaire', reponse: nomme }; voie = 'annuaire'; }
  } catch (e) {
    console.log('Annuaire indisponible :', e.message);
  }
}

/* 2. Le sens ensuite, seulement pour ce que les motifs ont rate. */
if (!trouve && question.length > 3) {
  try {
    const rep = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://127.0.0.1:11434/api/embeddings',
      headers: { 'Content-Type': 'application/json' },
      body: { model: 'nomic-embed-text', prompt: question, keep_alive: '-1s' },
      json: true,
      timeout: 15000,
    });
    const v = (rep && rep.embedding) || null;
    if (v && v.length) {
      const client = new Client(PG_CONFIG);
      await client.connect();
      let refs = [];
      try {
        const r = await client.query("SELECT value FROM app_data WHERE key = 'faits_intentions'");
        refs = (r.rows.length && r.rows[0].value) || [];
      } finally {
        await client.end();
      }

      /* Similarite cosinus, calculee ici : cinquante-six vecteurs ne
         justifient pas d'ouvrir une base vectorielle. */
      let normeQ = 0;
      for (let i = 0; i < v.length; i += 1) normeQ += v[i] * v[i];
      normeQ = Math.sqrt(normeQ) || 1;

      const parIntention = {};
      for (const ref of refs) {
        const w = ref.v;
        if (!w || w.length !== v.length) continue;
        let produit = 0;
        let normeW = 0;
        for (let i = 0; i < v.length; i += 1) {
          produit += v[i] * w[i];
          normeW += w[i] * w[i];
        }
        const s = produit / (normeQ * (Math.sqrt(normeW) || 1));
        /* Le meilleur score PAR INTENTION : deux formulations de la meme
           intention ne doivent pas se faire concurrence. */
        if (!(ref.cle in parIntention) || s > parIntention[ref.cle]) parIntention[ref.cle] = s;
      }

      const classees = Object.keys(parIntention)
        .map((cle) => ({ cle, s: parIntention[cle] }))
        .sort((a, b) => b.s - a.s);
      const premier = classees[0];
      const second = classees[1];
      const tranche = premier && (!second || premier.s - second.s >= ECART_MINIMAL);

      if (premier && premier.s >= SEUIL_SENS && tranche) {
        const fait = FAITS.find((f) => f.cle === premier.cle);
        if (fait) {
          /* Meme choix que pour les motifs : la variante parlee si elle
             existe, le texte ecrit sinon. */
          const c1 = langue === 'en' ? 'en' : 'fr';
          const parlee = body.mode === 'vocal' ? fait.reponse[c1 + '_vocal'] : null;
          trouve = { cle: fait.cle, reponse: parlee || fait.reponse[c1] };
          voie = 'sens';
        }
      }
    }
  } catch (e) {
    /* La reconnaissance par le sens est un CONFORT. Si elle echoue, la
       question part a la fiche comme avant : on ne prive personne de reponse
       parce qu'un plongement n'a pas abouti. */
    console.log('Reconnaissance par le sens indisponible :', e.message);
  }
}

/* ON N'ACCUEILLE LES GENS QU'UNE FOIS — ici aussi.

   La consigne posee sur la fiche ne peut rien pour ces reponses : elles
   sont ecrites en dur et ne passent pas par le modele. Quand la
   conversation a deja commence, on retire donc la formule d'accueil en
   tete. La salutation garde la sienne : c'est sa raison d'etre. */
if (trouve && trouve.cle !== 'salutation'
    && Array.isArray(body.history) && body.history.length) {
  const ACCUEILS = [
    'Bonjour et bienvenue chez ST DIGITAL.',
    'Bienvenue chez ST DIGITAL.',
    'Hello and welcome to ST DIGITAL.',
    'Welcome to ST DIGITAL.',
  ];
  for (const formule of ACCUEILS) {
    if (trouve.reponse.startsWith(formule)) {
      trouve.reponse = trouve.reponse.slice(formule.length).trim();
      break;
    }
  }
}

return [{
  json: {
    body,
    faitConnu: !!trouve,
    faitCle: trouve ? trouve.cle : null,
    /* Utile a la recette : savoir quel chemin a servi quelle question. */
    voie: voie,
    response: trouve ? trouve.reponse : null,
  },
}];

const crypto = require('crypto');

/* L'ADRESSE DE LA BORNE ET L'EXPEDITEUR SONT DANS LA CONFIGURATION.

   Le lien de reponse nomme la machine et le reseau prive : il decrit
   l'installation, donc il n'a rien a faire dans un code versionne. Meme
   chose pour l'expediteur des courriels, qui doit pouvoir changer sans
   toucher au flux. */
const SITE = JSON.parse(
  require('fs').readFileSync('/home/node/.n8n/isaac-site.json', 'utf8'));
const RESPOND_BASE = SITE.respondBase;

const { Client } = require('pg');
/* LES IDENTIFIANTS NE SONT PLUS DANS CE CODE.

   Ils sont lus dans un fichier du volume de n8n, hors du depot et hors de
   l'export. Changer de serveur ou faire tourner le mot de passe ne demande
   plus que de reecrire ce fichier — une fois, pas cinq.

   `fs` est autorise dans les noeuds Code de cette instance. Si le fichier
   manque, l'appel echoue bruyamment : une base inaccessible doit se voir. */
const PG_CONFIG = JSON.parse(
  require('fs').readFileSync('/home/node/.n8n/isaac-pg.json', 'utf8'));

async function readJSON(name, fallback) {
  const key = name.replace(/\.json$/, '');
  const client = new Client(PG_CONFIG);
  await client.connect();
  try {
    const res = await client.query('SELECT value FROM app_data WHERE key = $1', [key]);
    return res.rows.length ? res.rows[0].value : fallback;
  } catch (e) {
    return fallback;
  } finally {
    await client.end();
  }
}
async function writeJSON(name, data) {
  const key = name.replace(/\.json$/, '');
  const client = new Client(PG_CONFIG);
  await client.connect();
  try {
    await client.query(
      'INSERT INTO app_data (key, value, updated_at) VALUES ($1, $2, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()',
      [key, JSON.stringify(data)]
    );
  } finally {
    await client.end();
  }
}
function genId(prefix) {
  return prefix + '_' + crypto.randomBytes(6).toString('hex');
}
function genValidationCode() {
  const alphabet = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  let out = '';
  for (let i = 0; i < 8; i++) out += alphabet[crypto.randomInt(alphabet.length)];
  return out;
}
/* Date du jour sur le site, pas sur le serveur. Les conteneurs tournent en UTC
   et Libreville est a UTC+1 : entre minuit et une heure, comparer a la date du
   serveur rejetterait un code parfaitement valable. */
function dateDuJour(tz) {
  return new Intl.DateTimeFormat('fr-CA', {
    timeZone: tz || 'Africa/Libreville',
    year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(new Date());
}

