/* Ajout atomique au journal : PostgreSQL concatene, on ne relit pas le tableau
   pour le reecrire. Une action qui echoue a se journaliser ne doit jamais faire
   echouer l'action elle-meme : le journal est une trace, pas un verrou. */
async function journalise(entree) {
  const client = new Client(PG_CONFIG);
  try {
    await client.connect();
    await client.query(
      "INSERT INTO app_data (key, value, updated_at) VALUES ('audit', $1::jsonb, now()) " +
      "ON CONFLICT (key) DO UPDATE SET value = " +
      "CASE WHEN jsonb_typeof(app_data.value) = 'array' THEN app_data.value || EXCLUDED.value ELSE EXCLUDED.value END, " +
      "updated_at = now()",
      [JSON.stringify([entree])]
    );
    await client.query(
      "UPDATE app_data SET value = (SELECT jsonb_agg(e) FROM (" +
      "  SELECT e FROM jsonb_array_elements(value) WITH ORDINALITY AS t(e, n)" +
      "  ORDER BY n OFFSET GREATEST(jsonb_array_length(value) - 3000, 0)" +
      ") s) WHERE key = 'audit' AND jsonb_array_length(value) > 3000"
    );
  } catch (e) {
    console.log('Journal indisponible :', e.message);
  } finally {
    try { await client.end(); } catch (e) {}
  }
}

/* Une action d'administration se journalise toujours de la meme facon : le site
