    /* Nomme la personne quand elle est identifiee. Reste vide pour un compte
       partage : on n'invente pas une identite qu'on n'a pas. */
    auteur: (acc && acc.userName) || null,
    auteurEmail: (acc && acc.userEmail) || null,
