const AUTORISER_COMPTES_PARTAGES = true;

const DUREE_SESSION = 12 * 60 * 60 * 1000;   // douze heures
const ECHECS_AVANT_BLOCAGE = 5;
/* Trois administrateurs actifs par site. La limite n'est pas technique : elle
