}

/* Les evenements qui touchent l'exploitation d'un site. L'administrateur
   general n'y a PAS acces : il voit qui a un compte, pas ce que le site fait.
   C'est toute la difference entre surveiller des acces et surveiller des gens. */
const EVENEMENTS_DE_SITE = [
  'admin_list_appointments', 'admin_update_status', 'admin_list_visits',
  'admin_close_visit', 'admin_list_conversations', 'admin_list_notifications',
  'admin_get_kb', 'admin_list_staff', 'admin_add_staff', 'admin_remove_staff',
