];
const DUREE_BLOCAGE = 15 * 60 * 1000;

/* scrypt est volontairement lent : c'est ce qui rend une attaque par
   dictionnaire couteuse. Le sel est propre a chaque compte, de sorte que deux
   personnes ayant le meme mot de passe n'ont pas la meme empreinte. */
function nouveauSel() {
  return crypto.randomBytes(16).toString('hex');
}
function empreinte(motDePasse, sel) {
  return crypto.scryptSync(String(motDePasse), sel, 32).toString('hex');
}
/* Comparaison a temps constant : comparer deux empreintes avec === laisse
   fuir, par le temps de reponse, le nombre de caracteres corrects. */
/* Une longueur ne fait pas un mot de passe. « 0000000000 » satisfaisait la
   seule regle qui existait. On refuse ici ce qu'un attaquant essaie en premier,
   et surtout ce qui se devine a partir de la personne elle-meme : son nom et
   son adresse sont publics dans le back-office. */
const MOTS_INTERDITS = ['motdepasse', 'password', 'azerty', 'qwerty', 'admin', 'isaac',
                        'stdigital', 'accueil', 'bonjour', 'datacenter', 'libreville',
                        'douala', 'abidjan', 'gabon', 'cameroun', 'ivoire'];
const LONGUEUR_MINIMALE = 10;

function motDePasseFaible(mdp, email, nom) {
  const m = String(mdp || '');
  if (m.length < LONGUEUR_MINIMALE) {
    return 'Le mot de passe doit contenir au moins ' + LONGUEUR_MINIMALE + ' caracteres';
  }
  const bas = m.toLowerCase();
  if (/^(.)\1+$/.test(m)) return 'Un mot de passe ne peut pas etre un seul caractere repete';
  if (/0123|1234|2345|3456|4567|5678|6789|abcd|bcde|cdef/.test(bas)) {
    return 'Le mot de passe ne doit pas contenir de suite evidente';
  }
  for (const mot of MOTS_INTERDITS) {
    if (bas.includes(mot)) return 'Le mot de passe ne doit pas contenir « ' + mot + ' »';
  }
  /* Le nom et l'adresse figurent dans la liste des comptes : les reprendre
     dans le mot de passe revient a le publier a cote. */
  const morceaux = []
    .concat(String(email || '').split('@')[0].split(/[._-]+/))
    .concat(String(nom || '').split(/\s+/))
    .map((x) => String(x).toLowerCase())
    .filter((x) => x.length >= 4);
  for (const morceau of morceaux) {
    if (bas.includes(morceau)) return 'Le mot de passe ne doit pas reprendre votre nom ni votre adresse';
  }
  return null;
}

function memeEmpreinte(a, b) {
  const x = Buffer.from(String(a), 'hex');
  const y = Buffer.from(String(b), 'hex');
  if (x.length !== y.length) return false;
  return crypto.timingSafeEqual(x, y);
}
function normaliseEmail(e) {
  return String(e || '').trim().toLowerCase();
}

async function getAdminAccounts() {
  return await readJSON('admin_accounts.json', DEFAULT_ADMIN_ACCOUNTS);
}
/* Authentification, par ordre de preference : un jeton de session, puis, le
   temps de la transition, le mot de passe partage du pays. Le resultat porte
   desormais l'identite de la personne quand elle est connue, ce qui permet au
   journal de la nommer. */
async function checkAdmin(b) {
  const jeton = String(b.sessionToken || '').trim();
  if (jeton) {
    const sessions = await readJSON('admin_sessions.json', []);
    const s = sessions.find((x) => x.token === jeton && x.expire > now);
    if (!s) return null;
    const users = await readJSON('admin_users.json', []);
    const u = users.find((x) => x.id === s.userId && x.actif !== false);
    if (!u) return null;
    const comptes = await getAdminAccounts();
    const pays = comptes[u.pays] || {};
    return {
      dataCenter: u.dataCenter || pays.dataCenter,
      label: pays.label || u.pays,
      country: u.pays,
      userId: u.id,
      userName: u.nom,
      userEmail: u.email,
      role: u.role || 'accueil',
    };
  }

  if (!AUTORISER_COMPTES_PARTAGES) return null;
  const accounts = await getAdminAccounts();
  const acc = accounts[b.adminCountry];
  if (!acc) return null;

  /* Le mot de passe partage doit etre freine comme la connexion nominative.
     Sans cela, il suffisait de frapper ici plutot qu'a l'autre porte pour
     essayer autant de mots de passe qu'on voulait. */
  const cle = 'partage:' + b.adminCountry;
  const tentatives = await readJSON('admin_tentatives.json', []);
  const bloc = tentatives.find((t) => t.email === cle);
  if (bloc && bloc.jusqua > now) return null;

  if (!verifieMotDePassePartage(acc, b.adminPassword)) {
    const reste = tentatives.filter((t) => t.email !== cle);
    const blocageExpire = bloc && bloc.jusqua > 0 && bloc.jusqua <= now;
    const echecs = (blocageExpire ? 0 : (bloc ? bloc.echecs : 0)) + 1;
    reste.push({ email: cle, echecs, jusqua: echecs >= ECHECS_AVANT_BLOCAGE ? now + DUREE_BLOCAGE : 0 });
    await writeJSON('admin_tentatives.json', reste);
    return null;
  }
  if (bloc) await writeJSON('admin_tentatives.json', tentatives.filter((t) => t.email !== cle));

  /* Compte partage : on ne sait pas qui agit, et le journal le dira ainsi
     plutot que de laisser croire a une identification.

     Son role n'est PAS « administrateur ». Ce mot de passe est connu de toute
     l'equipe et a circule : lui laisser creer des comptes nominatifs
     permanents, c'est laisser fabriquer un acces qui survivra a sa rotation.
     Il ne sert plus qu'a amorcer le premier compte du site. */
  return { ...acc, country: b.adminCountry, userId: null, userName: null, role: 'partage' };
}

/* Compatible avec les deux formats : empreinte salee pour les sites deja
   migres, mot de passe en clair pour les autres. Sans ce repli, la migration
   enfermerait dehors tout le monde d'un coup. */
function verifieMotDePassePartage(acc, fourni) {
  const propose = String(fourni || '');
  if (acc.empreinte && acc.sel) return memeEmpreinte(acc.empreinte, empreinte(propose, acc.sel));
  if (typeof acc.password !== 'string') return false;
  /* Meme en clair, la comparaison est a temps constant : il n'y a aucune raison
     de renseigner un attaquant sur le nombre de caracteres justes.

     Surtout, on n'utilise PAS memeEmpreinte ici. Elle interprete ses arguments
     en hexadecimal : deux mots de passe ordinaires y deviennent deux tampons
     VIDES, donc de meme longueur et egaux — n'importe quel mot de passe serait
     accepte. Verifie, et c'est un contournement complet de l'authentification.
     Le texte se compare par son condense, qui fait toujours trente-deux
     octets. */
  return memeTexte(acc.password, propose);
}

/* Comparaison a temps constant de deux textes quelconques. Les condenses ont
   toujours la meme longueur, ce qui evite le piege ci-dessus. */
function memeTexte(a, b) {
  const x = crypto.createHash('sha256').update(String(a), 'utf8').digest();
  const y = crypto.createHash('sha256').update(String(b), 'utf8').digest();
  return crypto.timingSafeEqual(x, y);
}

