          `<p>Bonjour,</p>` +
          (complement
            ? `<p>Le visiteur dont la demande vous a d&eacute;j&agrave; &eacute;t&eacute; transmise vient de laisser ses coordonn&eacute;es. Il s'agit de la <b>m&ecirc;me demande</b>, compl&eacute;t&eacute;e &mdash; pas d'une seconde.</p>`
            : `<p>Un visiteur a pos&eacute; &agrave; la borne d'accueil une question qui rel&egrave;ve de votre service : la r&eacute;ponse d&eacute;pend de sa situation, et Isaac ne pouvait donc pas la lui donner.</p>`) +
          blocInfo([
            ['Sa demande', question],
            ['Pour le recontacter', contact
              || "le visiteur n'a pas laiss&eacute; de coordonn&eacute;es"],
            ['Re&ccedil;ue', provenance],
          ]),
          complement ? 'Coordonn&eacute;es du visiteur' : 'Besoin client à qualifier'
        ),
        audience: 'staff',
      });
    });
  } else {
    /* La conduite a tenir n'est pas la meme selon l'endroit d'ou vient la
       demande. Descendre a l'accueil pour n'y trouver personne fait perdre du
       temps et laisse la demande sans reponse. */
    const dansLeHall = body.surPlace !== false;
    response = { accepted: true, message: "Un membre de l'equipe a ete prevenu." };
    emails.push({
      to: ACCUEIL_EMAIL,
      from: FROM,
      subject: dansLeHall
        ? "Visiteur en attente à l'accueil — besoin d'aide"
        : "Demande reçue à distance — à rappeler",
      html: wrapEmail(
        `<p>Bonjour,</p>` +
        (dansLeHall
          ? `<p>Un visiteur <b>attend à l'accueil</b> et a demandé à être mis en relation avec un membre de l'équipe.</p>`
          : `<p>Une personne a posé cette question <b>depuis le lien public</b>, elle n'est donc pas dans le hall. Il n'y a personne à aller voir à l'accueil.</p>`) +
        `<p><b>Question posée :</b> ${question}</p>` +
        (dansLeHall
          ? `<p>Merci de vous rendre à l'accueil dès que possible.</p>`
          : `<p>Isaac lui a demandé ses coordonnées ; si elle les a laissées, elles figurent dans le journal des conversations du back-office.</p>`),
        'Demande de mise en relation'
      ),
      audience: 'staff',
    });
  }
} else {
  httpStatus = 400;
  response = { error: 'Evenement inconnu', event };
}

if (emails.length) {
  const notifLog = await readJSON('notifications.json', []);
  emails.forEach((e) => notifLog.push({ timestamp: now, to: e.to, subject: e.subject, event, audience: e.audience || 'visitor' }));
  if (notifLog.length > 3000) notifLog.splice(0, notifLog.length - 3000);
  await writeJSON('notifications.json', notifLog);
}

return [{ json: { httpStatus, response, emails } }];
